installer-gui-script.script:
function checkSystem() {
  if (system.compareVersions(system.version.ProductVersion, '15.4') < 0) {
    my.result.title = 'macOS 15.4 or later is required';
    my.result.message = 'KindleDock uses the FSKit backend on Apple Silicon Macs.';
    return false;
  }
  return true;
}
function needsMacFUSE() {
  var info = system.files.plistAtPath('/Library/Filesystems/macfuse.fs/Contents/Info.plist');
  return !info || !info.CFBundleShortVersionString ||
    system.compareVersions(info.CFBundleShortVersionString, '5.5.0') < 0;
}
